import sys

def count_snakes(N):
    # Count snake numbers in [10, N]
    if N < 10:
        return 0
    s = str(N)
    n = len(s)
    total = 0
    # Numbers with fewer digits than n (and >= 2 digits)
    for d in range(2, n):
        for t in range(1, 10):
            total += t ** (d - 1)
    # Numbers with exactly n digits, <= N
    T = int(s[0])
    # top digit < T
    for t in range(1, T):
        total += t ** (n - 1)
    # top digit == T: remaining n-1 digits each < T and number <= s[1:]
    if T >= 1:
        rem = s[1:]
        tight = True
        ways = 0
        L = len(rem)
        for i, ch in enumerate(rem):
            di = int(ch)
            if not tight:
                break
            # choose digit d < di and d < T -> becomes not tight
            choices_less = min(di, T)
            ways += choices_less * (T ** (L - i - 1))
            # choose d == di: only valid (stays tight) if di < T
            if di < T:
                continue
            else:
                tight = False
                break
        if tight:
            ways += 1
        total += ways
    return total

def main():
    data = sys.stdin.read().split()
    L = int(data[0])
    R = int(data[1])
    print(count_snakes(R) - count_snakes(L - 1))

main()
